size(3cm);
pair A[];
for (int i=0; i<9; ++i) {
A[i] = rotate(22.5+45*i)*(1,0);
}
filldraw(A[0]--A[1]--A[2]--A[3]--A[4]--A[5]--A[6]--A[7]--cycle,gray,black);
for (int i=0; i<8; ++i) { dot(A[i]); }
</asy>

