D(arc((-2,0),1,300,360));
D(arc((0,0),1,0,180));
D(arc((2,0),1,180,360));
D(arc((4,0),1,0,180));
D(arc((6,0),1,180,240));
D((-1.5,-1)--(5.5,-1));</asy>
