int i;
for(i=0; i<5; i=i+1) {
filldraw((4i,0)--(4i+3,0)--(4i+3,2r[i])--(4i,2r[i])--cycle, black, black);
}
draw(origin--(19,0)--(19,16)--(0,16)--cycle, linewidth(0.9));
for(i=1; i<8; i=i+1) {
draw((0,2i)--(19,2i));
