draw((5,-3*sqrt(3))--(1,sqrt(3)));
draw((4,-4*sqrt(3))--(0,0));
draw((3,3*sqrt(3))--(5,3*sqrt(3)));
draw((2,2*sqrt(3))--(6,2*sqrt(3)));
draw((1,sqrt(3))--(7,sqrt(3)));
draw((-1,0)--(9,0));
