draw((2,-2*sqrt(3))--(6,-2*sqrt(3)));
draw((3,-3*sqrt(3))--(5,-3*sqrt(3)));
</asy>

<math>\text{(A)}\ 4 \qquad \text{(B)}\ 5 \qquad \text{(C)}\ 6 \qquad \text{(D)}\ 7 \qquad \text{(E)}\ 9</math>

